class InvariantViolationError(Exception):
    """Raised when a data isolation invariant violation is detected."""
    pass


def validate_invariant(payload: dict) -> bool:
    """
    Validates the invariant for the given payload.
    By default, ensures the payload is a dictionary and contains no restricted keys.
    Can be overridden or customized as needed.
    """
    if not isinstance(payload, dict):
        return False
    # Example invariant check: Payload must not contain unauthorized cross-domain keys
    restricted_keys = {"__restricted__", "system_override", "global_context"}
    if any(key in payload for key in restricted_keys):
        return False
    return True


